import { PIXEL_ART, PIXEL_DIGITS, pixelArtSize, type PixelArtName } from './pixel-art.ts'

// Generated by scripts/build-pixel-art.mjs from pixel-art.ts (one small SVG per picture).
const files = import.meta.glob<string>('../../assets/pixel/*.svg', { eager: true, query: '?url', import: 'default' })
const fileOf = (name: string) => files[`../../assets/pixel/${name}.svg`]

/** One pixel picture, decoration only (the words next to it say what it is). `digit`: 1–5. */
export function PixelImage({ name, digit, scale = 2, className }: { name?: PixelArtName; digit?: number; scale?: number; className?: string }) {
  const art = digit ? PIXEL_DIGITS[digit - 1] : PIXEL_ART[name ?? 'capsule']
  const { width, height } = pixelArtSize(art, scale)
  return <img className={`px-image${className ? ` ${className}` : ''}`} src={fileOf(digit ? `digit-${digit}` : name ?? 'capsule')} width={width} height={height} alt="" aria-hidden="true" draggable={false} decoding="async" />
}

/** The app's dithered night roof strip with the pixel capsule (dialog / call-chat head). */
export function PixelRoof() {
  return <span className="px-roof" aria-hidden="true"><PixelImage name="capsule" /></span>
}
